#!/usr/bin/env python3
"""RoboLab eai-standard/2.2 cube unstacking controller."""
import sys, time, json, argparse
sys.path.insert(0, '/opt/tools')
import numpy as np
from rcb_client import Robot


def robot():
    return Robot()


def capture(r, label='obs', depth=True):
    o = r.get_obs(depth=depth)
    from PIL import Image
    for c, a in o.last.items(): Image.fromarray(a).save(f'/app/output/{label}_{c}.png')
    if depth:
        for c, a in o.last_depth.items(): np.save(f'/app/output/{label}_{c}_depth.npy', a)
    print('STATUS', json.dumps(r.status()))
    print('PROPRIO', json.dumps(o.meta['proprio']['now']))
    return o


def world_point(o, spec, cam, u, v):
    """Unproject one OpenCV z-depth pixel to env-local world coordinates."""
    z = float(o.last_depth[cam][int(round(v)), int(round(u))])
    K = np.asarray(spec['cameras'][cam]['intrinsic_cv'], float)
    E = np.asarray(o.meta['cameras'][cam]['extrinsic_cv'], float)
    pc = z * np.linalg.inv(K) @ np.array([u, v, 1.0])
    return np.linalg.inv(E[:,:3]) @ (pc - E[:,3]), z


def pose_rows(poses, gripper=0):
    return np.array([list(p[:7])+[gripper] for p in poses], np.float32)


def move(r, pose, gripper=0, note=''):
    """Single-target differential IK. pose=[x,y,z,qw,qx,qy,qz]."""
    res = r.submit('ee_pose', pose_rows([pose], gripper), video='none', note=note)
    print('MOVE', note, 'done=',res.done,'plan=',res.meta.get('plan'),'steps=',res.meta.get('control_steps_chunk'),'tcp=',res.meta.get('proprio',{}).get('now',[None]*15)[8:15])
    return res


def qnow(r):
    return np.asarray(r.get_obs(cameras=[]).meta['proprio']['now'], dtype=float)


def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('op', nargs='?', default='observe', choices=['observe','probe'])
    a=ap.parse_args()
    r=robot(); s=r.spec()
    print('STATUS',r.status())
    o=capture(r,'initial')
    if a.op=='probe':
        probes={'egocentric_mirrored_camera':[(400,180),(400,220),(400,250),(400,280)],
                'over_shoulder_left_camera':[(720,310),(720,335),(720,360),(720,385)]}
        for c, pts in probes.items():
            for uv in pts:
                print(c,uv,world_point(o,s,c,*uv))

if __name__=='__main__': main()
